mapper.update:
UPDATE pay_stripe
SET checkout_session_id = #{checkoutSessionId},
    checkout_url = #{checkoutUrl},
    update_time = #{updateTime}
WHERE id = #{id}
  AND status = 'CREATED'

UPDATE pay_stripe
SET status = 'FAILED',
    stripe_event_id = #{stripeEventId},
    update_time = #{updateTime}
WHERE checkout_session_id = #{checkoutSessionId}
  AND status != 'PAID'
